// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ───────────────────────────────────────────────────────────
// pinhole O             → SphereGeometry(0.09) black at origin
// Z axis black arrow    → cylinder shaft + cone, (0,0,Z) → (0,0,10.2)
// Y axis black arrow    → cylinder shaft + cone, O → (0,4.2,0)
// X axis black arrow    → cylinder shaft + cone, O → (3.6,0,0)   (recedes up-right)
// image plane           → PlaneGeometry(4.8,6) #E9ECEE @ z = -f-0.02 + black edge outline
// red Z segment         → cylinder r=.06  (0,0,0) → (0,0,Z)
// red f segment         → cylinder r=.06  (0,0,-f) → (0,0,0)
// red Y segment         → cylinder r=.06  (0,0,Z) → (0,Y,Z)
// red X segment         → cylinder r=.06  (0,0,Z) → (X,0,Z)
// red x segment (image) → cylinder r=.055 (0,0,-f) → (-fX/Z,0,-f)
// red y segment (image) → cylinder r=.055 (0,0,-f) → (0,-fY/Z,-f)
// green X-Z triangles   → 3-vertex BufferGeometry #7CE8A0 op .5 doubleSide (big + mirrored)
// cyan  Y-Z triangles   → 3-vertex BufferGeometry #7FF0EE op .5 doubleSide (big + mirrored)
// gray hypotenuses      → cylinders r=.018 #999 : O→(X,0,Z), O→(0,Y,Z), O→img corners
// gray drop-lines       → cylinders r=.018 #999 : P→(X,0,Z), P→(0,Y,Z)
// f leader tick         → cylinder r=.014 #999 (0,0,-f/2) → (0,-0.95,-f/2)
// dashed ray            → pool of cylinders r=.055 black, dash .22 / gap .16, P→O→p
// world point P         → SphereGeometry(0.20) #FF0000
// image point p         → SphereGeometry(0.16) #6B2E17
// green image axes      → arrows #00C000 along -X and -Y on the image plane
// labels X,Y,Z / x,y,f  → addLabel (upright serif / italic serif)
──────────────────────────────────────────────────────────────────────────── */

const root = new THREE.Group();
scene.add(root);

const COL = {
  red: 0xff0000, black: 0x111111, green: 0x7CE8A0, cyan: 0x7FF0EE,
  gray: 0x999999, brown: 0x6B2E17, plane: 0xE9ECEE, gx: 0x00C000
};

const AXY = new THREE.Vector3(0, 1, 0);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function orient(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) { mesh.visible = false; return; }
  mesh.visible = true;
  mesh.position.copy(a);
  mesh.quaternion.setFromUnitVectors(AXY, dir.divideScalar(len));
  mesh.scale.set(1, len, 1);
}

function tube(color, radius, parent) {
  const g = new THREE.CylinderGeometry(radius, radius, 1, 16, 1);
  g.translate(0, 0.5, 0);
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({ color }));
  (parent || root).add(m);
  return m;
}

function makeArrow(color, radius, headR, headL) {
  const grp = new THREE.Group();
  root.add(grp);
  const shaft = tube(color, radius, grp);
  const cg = new THREE.ConeGeometry(headR, headL, 20);
  cg.translate(0, headL / 2, 0);
  const head = new THREE.Mesh(cg, new THREE.MeshBasicMaterial({ color }));
  grp.add(head);
  grp.userData.set = (a, b) => {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();
    if (len < headL * 1.05) { grp.visible = false; return; }
    grp.visible = true;
    dir.divideScalar(len);
    const base = new THREE.Vector3().copy(b).addScaledVector(dir, -headL);
    orient(shaft, a, base);
    head.position.copy(base);
    head.quaternion.setFromUnitVectors(AXY, dir);
  };
  return grp;
}

function makeTri(color) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(9), 3));
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0.5, side: THREE.DoubleSide,
    depthWrite: false, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  }));
  m.renderOrder = 3;
  root.add(m);
  m.userData.set = (a, b, c) => {
    const p = g.attributes.position;
    p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z); p.setXYZ(2, c.x, c.y, c.z);
    p.needsUpdate = true;
    g.computeBoundingSphere();
  };
  return m;
}

/* ── static objects ─────────────────────────────────────────────────────── */
const pinhole = new THREE.Mesh(new THREE.SphereGeometry(0.09, 18, 14),
  new THREE.MeshBasicMaterial({ color: COL.black }));
root.add(pinhole);

const zArr = makeArrow(COL.black, 0.05, 0.17, 0.45);
const yArr = makeArrow(COL.black, 0.05, 0.17, 0.45);
const xArr = makeArrow(COL.black, 0.05, 0.17, 0.45);
const gxArr = makeArrow(COL.gx, 0.028, 0.10, 0.30);
const gyArr = makeArrow(COL.gx, 0.028, 0.10, 0.30);

const planeMesh = new THREE.Mesh(new THREE.PlaneGeometry(4.8, 6.0),
  new THREE.MeshBasicMaterial({ color: COL.plane, transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false }));
