  m.renderOrder = 3;
  root.add(m);
  m.userData.set = (a, b, c) => {
    const p = g.attributes.position;
    p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z); p.setXYZ(2, c.x, c.y, c.z);
