// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ───────────────────────────────────────────────────────────
// pinhole O             → SphereGeometry(0.11) black at origin
// Z axis black arrow    → cylinder r=.06 + cone, (0,0,Z) → (0,0,9.5)
// Y axis black arrow    → cylinder r=.06 + cone, O → (0,4.1,0)
// X axis black arrow    → cylinder r=.06 + cone, O → (3.5,0,0)   (recedes up-right)
// image plane           → PlaneGeometry(4.8,6) #E9ECEE @ z=-f-0.02 + black edge outline
// red Z segment         → cylinder r=.10  (0,0,-f) → (0,0,Z)
// red Y segment         → cylinder r=.10  (0,0,Z) → (0,Y,Z)
// red X segment         → cylinder r=.10  (0,0,Z) → (X,0,Z)
// red x segment (image) → cylinder r=.09  (0,0,-f) → (-fX/Z,0,-f)
// red y segment (image) → cylinder r=.09  (0,0,-f) → (0,-fY/Z,-f)
// green X-Z wedges      → 3-vertex BufferGeometry #7CE8A0 op .55 doubleSide (big + mirror)
// cyan  Y-Z wedges      → 3-vertex BufferGeometry #7FF0EE op .55 doubleSide (big + mirror)
// gray hypotenuses      → cylinders r=.02 #999 : O→(X,0,Z), O→(0,Y,Z), O→image corners
// gray drop-lines       → cylinders r=.02 #999 : P→(X,0,Z), P→(0,Y,Z)
// f leader tick         → cylinder r=.016 #999 (0,0,-f/2) → (0,-1.0,-f/2)
// dashed ray            → pool of cylinders r=.075 black, dash .22 / gap .15, P→O→p
// world point P         → SphereGeometry(0.28) #FF0000 depthTest off
// image point p         → SphereGeometry(0.24) #6B2E17 depthTest off, in front of plane
// green image axes      → arrows #00C000 along -X and -Y on the image plane
// labels X,Y,Z / x,y,f  → addLabel, big serif (upright caps / italic lowercase)
──────────────────────────────────────────────────────────────────────────── */

const root = new THREE.Group();
scene.add(root);

const COL = {
  red: 0xff0000, black: 0x111111, green: 0x7CE8A0, cyan: 0x7FF0EE,
  gray: 0x999999, brown: 0x6B2E17, plane: 0xE9ECEE, gx: 0x00C000
};

const AXY = new THREE.Vector3(0, 1, 0);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

function orient(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (len < 1e-6) { mesh.visible = false; return; }
  mesh.visible = true;
  mesh.position.copy(a);
  mesh.quaternion.setFromUnitVectors(AXY, dir.divideScalar(len));
  mesh.scale.set(1, len, 1);
}

function tube(color, radius, parent, opts) {
  const g = new THREE.CylinderGeometry(radius, radius, 1, 16, 1);
  g.translate(0, 0.5, 0);
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial(
    Object.assign({ color }, opts || {})));
  (parent || root).add(m);
  return m;
}

function makeArrow(color, radius, headR, headL) {
  const grp = new THREE.Group();
  root.add(grp);
  const shaft = tube(color, radius, grp);
  const cg = new THREE.ConeGeometry(headR, headL, 22);
  cg.translate(0, headL / 2, 0);
  const head = new THREE.Mesh(cg, new THREE.MeshBasicMaterial({ color }));
  grp.add(head);
  grp.userData.set = (a, b) => {
    const dir = new THREE.Vector3().subVectors(b, a);
    const len = dir.length();
    if (len < headL * 1.05) { grp.visible = false; return; }
    grp.visible = true;
    dir.divideScalar(len);
    const base = new THREE.Vector3().copy(b).addScaledVector(dir, -headL);
    orient(shaft, a, base);
    head.position.copy(base);
    head.quaternion.setFromUnitVectors(AXY, dir);
  };
  return grp;
}

function makeTri(color) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(9), 3));
  const m = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color, transparent: true, opacity: 0.55, side: THREE.DoubleSide,
    depthWrite: false, polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
  }));
  m.renderOrder = 3;
  root.add(m);
  m.userData.set = (a, b, c) => {
    const p = g.attributes.position;
    p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z); p.setXYZ(2, c.x, c.y, c.z);
    p.needsUpdate = true;
    g.computeBoundingSphere();
  };
  return m;
}

/* ── static objects ─────────────────────────────────────────────────────── */
const pinhole = new THREE.Mesh(new THREE.SphereGeometry(0.11, 20, 16),
  new THREE.MeshBasicMaterial({ color: COL.black }));
root.add(pinhole);

const zArr = makeArrow(COL.black, 0.06, 0.20, 0.55);
const yArr = makeArrow(COL.black, 0.06, 0.20, 0.55);
const xArr = makeArrow(COL.black, 0.06, 0.20, 0.55);
const gxArr = makeArrow(COL.gx, 0.035, 0.13, 0.36);
const gyArr = makeArrow(COL.gx, 0.035, 0.13, 0.36);

const planeMesh = new THREE.Mesh(new THREE.PlaneGeometry(4.8, 6.0),
  new THREE.MeshBasicMaterial({ color: COL.plane, transparent: true, opacity: 0.9, side: THREE.DoubleSide, depthWrite: false }));
planeMesh.renderOrder = 1;
root.add(planeMesh);
const planeEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.PlaneGeometry(4.8, 6.0)),
  new THREE.LineBasicMaterial({ color: 0x222222 }));
planeEdges.renderOrder = 2;
root.add(planeEdges);

const RW = 0.10, RI = 0.09;
const zSeg = tube(COL.red, RW); zSeg.renderOrder = 4;
const fSeg = tube(COL.red, RW); fSeg.renderOrder = 4;
const ySeg = tube(COL.red, RW); ySeg.renderOrder = 4;
const xSeg = tube(COL.red, RW); xSeg.renderOrder = 4;
const xImg = tube(COL.red, RI); xImg.renderOrder = 4;
const yImg = tube(COL.red, RI); yImg.renderOrder = 4;
const allRedSegs = [zSeg, fSeg, ySeg, xSeg, xImg, yImg];

const greenBig = makeTri(COL.green);
const greenSmall = makeTri(COL.green);
const cyanBig = makeTri(COL.cyan);
const cyanSmall = makeTri(COL.cyan);
const allTris = [greenBig, greenSmall, cyanBig, cyanSmall];

const hypG = tube(COL.gray, 0.02);
const hypC = tube(COL.gray, 0.02);
const hypGi = tube(COL.gray, 0.016);
const hypCi = tube(COL.gray, 0.016);
const dropX = tube(COL.gray, 0.02);
const dropY = tube(COL.gray, 0.02);
const fTick = tube(COL.gray, 0.016);

const ptP = new THREE.Mesh(new THREE.SphereGeometry(0.28, 28, 20),
  new THREE.MeshBasicMaterial({ color: COL.red, depthTest: false }));
ptP.renderOrder = 12;
root.add(ptP);
const pickP = new THREE.Mesh(new THREE.SphereGeometry(0.55, 12, 10),
  new THREE.MeshBasicMaterial({ visible: false }));
ptP.add(pickP);

const ptImg = new THREE.Mesh(new THREE.SphereGeometry(0.24, 28, 20),
  new THREE.MeshBasicMaterial({ color: COL.brown, depthTest: false }));
ptImg.renderOrder = 12;
root.add(ptImg);

/* dashed ray pool */
const dashGroup = new THREE.Group();
root.add(dashGroup);
const dashPool = [];
function dashAt(i) {
  if (!dashPool[i]) {
    const t = tube(COL.black, 0.075, dashGroup, { depthTest: false });
    t.renderOrder = 8;
    dashPool[i] = t;
  }
  return dashPool[i];
}
function layDashes(a, b, start) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const L = dir.length();
  if (L < 1e-5) return start;
  dir.divideScalar(L);
  const dash = 0.22, gap = 0.15, per = dash + gap;
  let t = 0, i = start;
  const p0 = new THREE.Vector3(), p1 = new THREE.Vector3();
  while (t < L - 1e-4 && i < 140) {
    const e = Math.min(t + dash, L);
    p0.copy(a).addScaledVector(dir, t);
    p1.copy(a).addScaledVector(dir, e);
    orient(dashAt(i++), p0, p1);
    t += per;
  }
  return i;
}

/* ── state ──────────────────────────────────────────────────────────────── */
const P0 = new THREE.Vector3(-3.4, 2.2, 6);
const state = { f: 2.0, fTarget: 2.0, P: P0.clone(), corr: 'off' };

const O = new THREE.Vector3(0, 0, 0);
const vCz = new THREE.Vector3(), vCx = new THREE.Vector3(), vCy = new THREE.Vector3();
const vIc = new THREE.Vector3(), vIx = new THREE.Vector3(), vIy = new THREE.Vector3(), vP2 = new THREE.Vector3();

let labX, labY, labZ, labx, laby, labf;

function refresh() {
  const f = state.f, P = state.P;
  const Xp = P.x, Yp = P.y, Zp = P.z;
  const ix = -f * Xp / Zp, iy = -f * Yp / Zp;

  vCz.set(0, 0, Zp); vCx.set(Xp, 0, Zp); vCy.set(0, Yp, Zp);
  vIc.set(0, 0, -f); vIx.set(ix, 0, -f); vIy.set(0, iy, -f);
  vP2.set(ix, iy, -f + 0.09);

  // axes
  zArr.userData.set(vCz, new THREE.Vector3(0, 0, Math.max(9.5, Zp + 1.8)));
  yArr.userData.set(O, new THREE.Vector3(0, 4.1, 0));
  xArr.userData.set(O, new THREE.Vector3(3.5, 0, 0));
  gxArr.userData.set(new THREE.Vector3(0, 0, -f + 0.05), new THREE.Vector3(-2.3, 0, -f + 0.05));
  gyArr.userData.set(new THREE.Vector3(0, 0, -f + 0.05), new THREE.Vector3(0, -2.8, -f + 0.05));

  // image plane
  planeMesh.position.set(0, 0, -f - 0.03);
  planeEdges.position.set(0, 0, -f - 0.03);

  // red segments
  orient(zSeg, O, vCz);
  orient(fSeg, vIc, O);
  orient(ySeg, vCz, vCy);
  orient(xSeg, vCz, vCx);
  orient(xImg, vIc, vIx);
  orient(yImg, vIc, vIy);

  // shaded cross-sections
  greenBig.userData.set(O, vCz, vCx);
  greenSmall.userData.set(O, vIc, vIx);
  cyanBig.userData.set(O, vCz, vCy);
  cyanSmall.userData.set(O, vIc, vIy);

  // thin gray helpers
  orient(hypG, O, vCx);
  orient(hypC, O, vCy);
  orient(hypGi, O, vIx);
  orient(hypCi, O, vIy);
  orient(dropX, P, vCx);
  orient(dropY, P, vCy);
  orient(fTick, new THREE.Vector3(0, 0, -f / 2), new THREE.Vector3(0, -1.0, -f / 2));

  // points + dashed ray
  ptP.position.copy(P);
  ptImg.position.copy(vP2);
  let used = layDashes(P, O, 0);
  used = layDashes(O, new THREE.Vector3(ix, iy, -f), used);
  for (let k = used; k < dashPool.length; k++) dashPool[k].visible = false;

  // labels
  if (labX) {
    labX.pos.set(Xp * 0.80, 0, Zp);
    labY.pos.set(0, Yp * 0.62, Zp);
    labZ.pos.set(0, 0, Zp * 0.55);
    labx.pos.set(ix * 0.55, 0, -f);
    laby.pos.set(0, iy * 0.62, -f);
    labf.pos.set(0, -1.22, -f / 2);
  }

  // equation readout
  const eqXZ = document.getElementById('eqXZ');
  const eqYZ = document.getElementById('eqYZ');
  const eqP = document.getElementById('eqP');
  if (eqXZ) {
    const xi = f * Xp / Zp, yi = f * Yp / Zp;
    const onXZ = (state.corr === 'xz' || state.corr === 'both');
    const onYZ = (state.corr === 'yz' || state.corr === 'both');
    eqXZ.innerHTML = '<i>x</i>/<i>f</i> = <i>X</i>/<i>Z</i> &nbsp;→&nbsp; ' +
      xi.toFixed(2) + '/' + f.toFixed(2) + ' = ' + Xp.toFixed(2) + '/' + Zp.toFixed(2) +
      ' = ' + (Xp / Zp).toFixed(3);
    eqYZ.innerHTML = '<i>y</i>/<i>f</i> = <i>Y</i>/<i>Z</i> &nbsp;→&nbsp; ' +
      yi.toFixed(2) + '/' + f.toFixed(2) + ' = ' + Yp.toFixed(2) + '/' + Zp.toFixed(2) +
      ' = ' + (Yp / Zp).toFixed(3);
    eqXZ.style.color = onXZ ? '#0a7a2f' : '#333';
    eqXZ.style.fontWeight = onXZ ? '700' : '400';
    eqYZ.style.color = onYZ ? '#0a6e86' : '#333';
    eqYZ.style.fontWeight = onYZ ? '700' : '400';
    eqP.textContent = 'P = (' + Xp.toFixed(2) + ', ' + Yp.toFixed(2) + ', ' + Zp.toFixed(2) +
      ')   p = (' + (-xi).toFixed(2) + ', ' + (-yi).toFixed(2) + ', −f)';
  }
}

refresh();

/* ── camera (perspective, narrow FOV so it reads near-parallel) ─────────── */
const VIEW = { projection: 'perspective', azimuthDeg: 163, elevationDeg: 22, rollDeg: 0, heightFraction: 0.92 };
setCameraView(VIEW);
camera.fov = 28;
camera.updateProjectionMatrix();
setCameraView(VIEW);
document.getElementById('btnReset').style.display = '';

/* ── labels (compensated for the perspective distance scaling) ──────────── */
const SER = "Georgia,'Times New Roman',serif";
const LABS = [];
function mkLabel(html, px, opts) {
  const e = addLabel(html, new THREE.Vector3(), Object.assign({
    fontSize: px + 'px', background: 'rgba(255,255,255,0.72)'
  }, opts || {}));
  LABS.push({ e, px });
  return e;
}
labX = mkLabel('<span style="font-family:' + SER + '">X</span>', 30, { offset: [42, 26] });
labY = mkLabel('<span style="font-family:' + SER + '">Y</span>', 30, { offset: [40, -6] });
labZ = mkLabel('<span style="font-family:' + SER + '">Z</span>', 30, { offset: [0, -30] });
labx = mkLabel('<i style="font-family:' + SER + '">x</i>', 26, { offset: [-22, -26], color: '#1a1a1a' });
laby = mkLabel('<i style="font-family:' + SER + '">y</i>', 26, { offset: [-34, 8], color: '#1a1a1a' });
labf = mkLabel('<i style="font-family:' + SER + '">f</i>', 26, { offset: [0, 8], color: '#1a1a1a' });

let _lastK = -1;
function applyLabelScale() {
  const dist = camera.position.distanceTo(controls.target);
  const k = camera.isPerspectiveCamera ? Math.max(0.5, dist / 8) : 1;
  if (_lastK > 0 && Math.abs(k - _lastK) / _lastK < 0.02) return;
  _lastK = k;
  for (const L of LABS) L.e.div.style.fontSize = (L.px * k).toFixed(1) + 'px';
}
applyLabelScale();
refresh();

/* ── hover / click explanations ─────────────────────────────────────────── */
registerInteractive(ptP, {
  title: 'World point P = (X, Y, Z)',
  tooltip: 'Drag to move P (Shift = depth)',
  body: 'The 3D scene point. Its coordinates X, Y and its depth Z set the two large right triangles. Drag it: both cross-sections rescale together because they share one ray through the pinhole.'
});
registerInteractive(ptImg, {
  title: 'Image point p = (−fX/Z, −fY/Z)',
  tooltip: 'Projected (inverted) image point',
  body: 'Where the ray pierces the image plane at distance f behind the pinhole. Because the plane is behind the optical center, the image is inverted in both x and y.'
});
registerInteractive(greenBig, {
  title: 'X–Z cross-section (green)',
  tooltip: 'Similar triangles: x/f = X/Z',
  body: 'The large triangle has legs X and Z; the mirrored small triangle on the image side has legs x and f. They share the apex angle at the pinhole, so x/f = X/Z.'
});
registerInteractive(cyanBig, {
  title: 'Y–Z cross-section (cyan)',
  tooltip: 'Similar triangles: y/f = Y/Z',
  body: 'The identical argument in the perpendicular plane: legs Y and Z versus y and f, giving y/f = Y/Z from the very same ray.'
});
registerInteractive(planeMesh, {
  title: 'Image plane (Z = −f)',
  tooltip: 'Image plane at distance f',
  body: 'A plane perpendicular to the optical axis, a focal length f behind the pinhole. Increasing f magnifies the image linearly.'
});

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const fSlider = document.getElementById('fSlider');
const fVal = document.getElementById('fVal');
const zSlider = document.getElementById('zSlider');
const zVal = document.getElementById('zVal');
const corrSel = document.getElementById('corrSel');

function syncSliders() {
  fSlider.value = state.f.toFixed(2);
  fVal.textContent = state.f.toFixed(2);
  zSlider.value = state.P.z.toFixed(1);
  zVal.textContent = state.P.z.toFixed(1);
}
syncSliders();

fSlider.addEventListener('input', () => {
  state.f = parseFloat(fSlider.value);
  state.fTarget = state.f;
  fVal.textContent = state.f.toFixed(2);
  refresh();
});
zSlider.addEventListener('input', () => {
  state.P.z = parseFloat(zSlider.value);
  zVal.textContent = state.P.z.toFixed(1);
  refresh();
});
corrSel.addEventListener('change', () => { state.corr = corrSel.value; refresh(); });
document.getElementById('btnResetP').addEventListener('click', () => {
  state.P.copy(P0);
  syncSliders();
  refresh();
});

/* ── drag the world point P ─────────────────────────────────────────────── */
const dragRay = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const dragPlane = new THREE.Plane();
const hitPt = new THREE.Vector3();
let dragMode = null;

function setNDC(e) {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
function setupPlane(mode) {
  const n = (mode === 'z') ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 0, 1);
  dragPlane.setFromNormalAndCoplanarPoint(n, state.P);
}

canvas.addEventListener('pointerdown', (e) => {
  setNDC(e);
  dragRay.setFromCamera(ndc, camera);
  const hits = dragRay.intersectObject(pickP, false);
  if (hits.length) {
    dragMode = e.shiftKey ? 'z' : 'xy';
    setupPlane(dragMode);
