  const p0 = new THREE.Vector3(), p1 = new THREE.Vector3();
  while (t < L - 1e-4 && i < 140) {
    const e = Math.min(t + dash, L);
    p0.copy(a).addScaledVector(dir, t);
    p1.copy(a).addScaledVector(dir, e);
    orient(dashAt(i++), p0, p1);
    t += per;
  }
  return i;
}

/* ── state ──────────────────────────────────────────────────────────────── */
const P0 = new THREE.Vector3(-3.4, 2.2, 6);
const state = { f: 2.0, fTarget: 2.0, P: P0.clone(), corr: 'off' };

const O = new THREE.Vector3(0, 0, 0);
const vCz = new THREE.Vector3(), vCx = new THREE.Vector3(), vCy = new THREE.Vector3();
const vIc = new THREE.Vector3(), vIx = new THREE.Vector3(), vIy = new THREE.Vector3(), vP2 = new THREE.Vector3();

let labX, labY, labZ, labx, laby, labf;

function refresh() {
  const f = state.f, P = state.P;
  const Xp = P.x, Yp = P.y, Zp = P.z;
  const ix = -f * Xp / Zp, iy = -f * Yp / Zp;

  vCz.set(0, 0, Zp); vCx.set(Xp, 0, Zp); vCy.set(0, Yp, Zp);
  vIc.set(0, 0, -f); vIx.set(ix, 0, -f); vIy.set(0, iy, -f);
  vP2.set(ix, iy, -f + 0.09);

  // axes
  zArr.userData.set(vCz, new THREE.Vector3(0, 0, Math.max(9.5, Zp + 1.8)));
  yArr.userData.set(O, new THREE.Vector3(0, 4.1, 0));
  xArr.userData.set(O, new THREE.Vector3(3.5, 0, 0));
  gxArr.userData.set(new THREE.Vector3(0, 0, -f + 0.05), new THREE.Vector3(-2.3, 0, -f + 0.05));
  gyArr.userData.set(new THREE.Vector3(0, 0, -f + 0.05), new THREE.Vector3(0, -2.8, -f + 0.05));

  // image plane
  planeMesh.position.set(0, 0, -f - 0.03);
  planeEdges.position.set(0, 0, -f - 0.03);

  // red segments
  orient(zSeg, O, vCz);
  orient(fSeg, vIc, O);
  orient(ySeg, vCz, vCy);
  orient(xSeg, vCz, vCx);
  orient(xImg, vIc, vIx);
  orient(yImg, vIc, vIy);

  // shaded cross-sections
  greenBig.userData.set(O, vCz, vCx);
  greenSmall.userData.set(O, vIc, vIx);
  cyanBig.userData.set(O, vCz, vCy);
  cyanSmall.userData.set(O, vIc, vIy);

  // thin gray helpers
  orient(hypG, O, vCx);
  orient(hypC, O, vCy);
  orient(hypGi, O, vIx);
  orient(hypCi, O, vIy);
  orient(dropX, P, vCx);
  orient(dropY, P, vCy);
  orient(fTick, new THREE.Vector3(0, 0, -f / 2), new THREE.Vector3(0, -1.0, -f / 2));

  // points + dashed ray
  ptP.position.copy(P);
  ptImg.position.copy(vP2);
  let used = layDashes(P, O, 0);
  used = layDashes(O, new THREE.Vector3(ix, iy, -f), used);
  for (let k = used; k < dashPool.length; k++) dashPool[k].visible = false;

  // labels
  if (labX) {
    labX.pos.set(Xp * 0.80, 0, Zp);
    labY.pos.set(0, Yp * 0.62, Zp);
    labZ.pos.set(0, 0, Zp * 0.55);
    labx.pos.set(ix * 0.55, 0, -f);
    laby.pos.set(0, iy * 0.62, -f);
    labf.pos.set(0, -1.22, -f / 2);
  }

  // equation readout
  const eqXZ = document.getElementById('eqXZ');
  const eqYZ = document.getElementById('eqYZ');
  const eqP = document.getElementById('eqP');
  if (eqXZ) {
    const xi = f * Xp / Zp, yi = f * Yp / Zp;
    const onXZ = (state.corr === 'xz' || state.corr === 'both');
    const onYZ = (state.corr === 'yz' || state.corr === 'both');
    eqXZ.innerHTML = '<i>x</i>/<i>f</i> = <i>X</i>/<i>Z</i> &nbsp;→&nbsp; ' +
      xi.toFixed(2) + '/' + f.toFixed(2) + ' = ' + Xp.toFixed(2) + '/' + Zp.toFixed(2) +
      ' = ' + (Xp / Zp).toFixed(3);
    eqYZ.innerHTML = '<i>y</i>/<i>f</i> = <i>Y</i>/<i>Z</i> &nbsp;→&nbsp; ' +
      yi.toFixed(2) + '/' + f.toFixed(2) + ' = ' + Yp.toFixed(2) + '/' + Zp.toFixed(2) +
      ' = ' + (Yp / Zp).toFixed(3);
    eqXZ.style.color = onXZ ? '#0a7a2f' : '#333';
    eqXZ.style.fontWeight = onXZ ? '700' : '400';
    eqYZ.style.color = onYZ ? '#0a6e86' : '#333';
    eqYZ.style.fontWeight = onYZ ? '700' : '400';
    eqP.textContent = 'P = (' + Xp.toFixed(2) + ', ' + Yp.toFixed(2) + ', ' + Zp.toFixed(2) +
      ')   p = (' + (-xi).toFixed(2) + ', ' + (-yi).toFixed(2) + ', −f)';
  }
}

refresh();

/* ── camera (perspective, narrow FOV so it reads near-parallel) ─────────── */
const VIEW = { projection: 'perspective', azimuthDeg: 163, elevationDeg: 22, rollDeg: 0, heightFraction: 0.92 };
setCameraView(VIEW);
camera.fov = 28;
camera.updateProjectionMatrix();
setCameraView(VIEW);
document.getElementById('btnReset').style.display = '';

/* ── labels (compensated for the perspective distance scaling) ──────────── */
const SER = "Georgia,'Times New Roman',serif";
const LABS = [];
function mkLabel(html, px, opts) {
  const e = addLabel(html, new THREE.Vector3(), Object.assign({
    fontSize: px + 'px', background: 'rgba(255,255,255,0.72)'
  }, opts || {}));
  LABS.push({ e, px });
  return e;
}
labX = mkLabel('<span style="font-family:' + SER + '">X</span>', 30, { offset: [42, 26] });
labY = mkLabel('<span style="font-family:' + SER + '">Y</span>', 30, { offset: [40, -6] });
labZ = mkLabel('<span style="font-family:' + SER + '">Z</span>', 30, { offset: [0, -30] });
labx = mkLabel('<i style="font-family:' + SER + '">x</i>', 26, { offset: [-22, -26], color: '#1a1a1a' });
laby = mkLabel('<i style="font-family:' + SER + '">y</i>', 26, { offset: [-34, 8], color: '#1a1a1a' });
labf = mkLabel('<i style="font-family:' + SER + '">f</i>', 26, { offset: [0, 8], color: '#1a1a1a' });

let _lastK = -1;
function applyLabelScale() {
  const dist = camera.position.distanceTo(controls.target);
  const k = camera.isPerspectiveCamera ? Math.max(0.5, dist / 8) : 1;
  if (_lastK > 0 && Math.abs(k - _lastK) / _lastK < 0.02) return;
  _lastK = k;
  for (const L of LABS) L.e.div.style.fontSize = (L.px * k).toFixed(1) + 'px';
}
applyLabelScale();
refresh();

/* ── hover / click explanations ─────────────────────────────────────────── */
registerInteractive(ptP, {
  title: 'World point P = (X, Y, Z)',
  tooltip: 'Drag to move P (Shift = depth)',
  body: 'The 3D scene point. Its coordinates X, Y and its depth Z set the two large right triangles. Drag it: both cross-sections rescale together because they share one ray through the pinhole.'
});
registerInteractive(ptImg, {
  title: 'Image point p = (−fX/Z, −fY/Z)',
  tooltip: 'Projected (inverted) image point',
  body: 'Where the ray pierces the image plane at distance f behind the pinhole. Because the plane is behind the optical center, the image is inverted in both x and y.'
});
registerInteractive(greenBig, {
  title: 'X–Z cross-section (green)',
  tooltip: 'Similar triangles: x/f = X/Z',
  body: 'The large triangle has legs X and Z; the mirrored small triangle on the image side has legs x and f. They share the apex angle at the pinhole, so x/f = X/Z.'
});
registerInteractive(cyanBig, {
  title: 'Y–Z cross-section (cyan)',
  tooltip: 'Similar triangles: y/f = Y/Z',
  body: 'The identical argument in the perpendicular plane: legs Y and Z versus y and f, giving y/f = Y/Z from the very same ray.'
});
registerInteractive(planeMesh, {
  title: 'Image plane (Z = −f)',
  tooltip: 'Image plane at distance f',
  body: 'A plane perpendicular to the optical axis, a focal length f behind the pinhole. Increasing f magnifies the image linearly.'
});

/* ── UI wiring ──────────────────────────────────────────────────────────── */
const fSlider = document.getElementById('fSlider');
const fVal = document.getElementById('fVal');
const zSlider = document.getElementById('zSlider');
const zVal = document.getElementById('zVal');
const corrSel = document.getElementById('corrSel');

function syncSliders() {
  fSlider.value = state.f.toFixed(2);
  fVal.textContent = state.f.toFixed(2);
  zSlider.value = state.P.z.toFixed(1);
  zVal.textContent = state.P.z.toFixed(1);
}
syncSliders();

fSlider.addEventListener('input', () => {
  state.f = parseFloat(fSlider.value);
  state.fTarget = state.f;
  fVal.textContent = state.f.toFixed(2);
  refresh();
});
zSlider.addEventListener('input', () => {
  state.P.z = parseFloat(zSlider.value);
  zVal.textContent = state.P.z.toFixed(1);
  refresh();
});
corrSel.addEventListener('change', () => { state.corr = corrSel.value; refresh(); });
document.getElementById('btnResetP').addEventListener('click', () => {
  state.P.copy(P0);
  syncSliders();
  refresh();
});

/* ── drag the world point P ─────────────────────────────────────────────── */
const dragRay = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const dragPlane = new THREE.Plane();
const hitPt = new THREE.Vector3();
let dragMode = null;

function setNDC(e) {
  const r = canvas.getBoundingClientRect();
  ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
function setupPlane(mode) {
  const n = (mode === 'z') ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 0, 1);
  dragPlane.setFromNormalAndCoplanarPoint(n, state.P);
}

canvas.addEventListener('pointerdown', (e) => {
  setNDC(e);
  dragRay.setFromCamera(ndc, camera);
  const hits = dragRay.intersectObject(pickP, false);
  if (hits.length) {
    dragMode = e.shiftKey ? 'z' : 'xy';
    setupPlane(dragMode);
    controls.enabled = false;
    canvas.style.cursor = 'grabbing';
    try { canvas.setPointerCapture(e.pointerId); } catch (err) { }
  }
});

canvas.addEventListener('pointermove', (e) => {
  if (!dragMode) return;
  const want = e.shiftKey ? 'z' : 'xy';
  if (want !== dragMode) { dragMode = want; setupPlane(dragMode); }
  setNDC(e);
  dragRay.setFromCamera(ndc, camera);
  if (dragRay.ray.intersectPlane(dragPlane, hitPt)) {
    if (dragMode === 'xy') {
      state.P.x = clamp(hitPt.x, -4, 4);
      state.P.y = clamp(hitPt.y, -3, 3.5);
    } else {
      state.P.z = clamp(hitPt.z, 2, 9);
    }
    syncSliders();
    refresh();
  }
});

function endDrag() {
  if (!dragMode) return;
  dragMode = null;
  controls.enabled = true;
  canvas.style.cursor = 'default';
}
window.addEventListener('pointerup', endDrag);
window.addEventListener('pointercancel', endDrag);

/* ── correspondence highlight pulse ─────────────────────────────────────── */
const HIGHLIGHT = {
  off: null,
  xz: { segs: [xSeg, xImg, fSeg, zSeg], tris: [greenBig, greenSmall] },
  yz: { segs: [ySeg, yImg, fSeg, zSeg], tris: [cyanBig, cyanSmall] },
  both: { segs: allRedSegs, tris: allTris }
};
const C_RED = new THREE.Color(0xff0000);
const C_HI = new THREE.Color(0xffd21e);
const C_TMP = new THREE.Color();

/* ── demo steps ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    t: 'The pinhole and the ray', f: 2.0, c: 'off',
    n: 'A world point P at depth Z sends a single dashed ray through the pinhole at the origin and strikes the image plane a distance f behind it, forming an inverted image point.'
  },
  {
    t: 'The X–Z triangle', f: 2.0, c: 'xz',
    n: 'Highlight the green cross-section: the small triangle (sides x and f) and the large triangle (sides X and Z) share the apex angle at the pinhole, so x/f = X/Z.'
  },
  {
    t: 'The Y–Z triangle', f: 2.0, c: 'yz',
    n: 'The cyan cross-section repeats the identical argument in the perpendicular plane, giving y/f = Y/Z from the very same ray.'
  },
  {
    t: 'Changing the focal length', f: 3.6, c: 'both',
    n: 'Push the image plane farther from the pinhole: x and y both grow in proportion to f while X, Y and Z are untouched — the image simply magnifies.'
  },
  {
    t: 'Move the point', f: 2.0, c: 'both',
    n: 'Drag P anywhere in the scene: pushing it deeper shrinks both image coordinates, sliding it sideways or up moves the image point oppositely — projection is inverted.'
  }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  state.fTarget = s.f;
  state.corr = s.c;
  corrSel.value = s.c;
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.t;
  document.getElementById('stepText').textContent = s.n;
  document.getElementById('stepIdx').textContent = (stepIdx + 1) + ' / ' + STEPS.length;
  refresh();
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── auxiliary loop: focal tween + highlight pulse + label sizing ───────── */
function figTick() {
  requestAnimationFrame(figTick);
  if (Math.abs(state.f - state.fTarget) > 0.003) {
    state.f += (state.fTarget - state.f) * 0.12;
    syncSliders();
    refresh();
  }
  applyLabelScale();
  const k = 0.5 + 0.5 * Math.sin(performance.now() * 0.005);
  const set = HIGHLIGHT[state.corr];
  for (const s of allRedSegs) s.material.color.copy(C_RED);
  for (const t of allTris) t.material.opacity = 0.55;
  if (set) {
    C_TMP.copy(C_RED).lerp(C_HI, k);
    for (const s of set.segs) s.material.color.copy(C_TMP);
    for (const t of set.tris) t.material.opacity = 0.55 + 0.28 * k;
  }
}
figTick();
// @FIGURE_CODE_END

